const fetch = require('node-fetch');
const { URLSearchParams } = require('url');
const solr = JSON.parse($vars.solr_config);
// ════════════════════════════════════════════════════════════════
//  CONFIGURATION
// ════════════════════════════════════════════════════════════════
const AUTH     = Buffer.from(`${solr.user}:${solr.pass}`).toString("base64");
const SOLR_URL = `${solr.base_url}/products/select`;
const EMBED_URL = $vars.endpoint+':5000/embed';

const DEFAULT_LIMIT = 5;
const MAX_LIMIT     = 50;
const FETCH_K       = 60;  // candidates before re-ranking

// ════════════════════════════════════════════════════════════════
//  PRICE EXTRACTION
// ════════════════════════════════════════════════════════════════
function extractPriceFromQuery(query) {
  const q = query.replace(/[$,₹]/g, '');
  const between = q.match(/between\s+(\d+)\s+(?:and|to)\s+(\d+)/i);
  if (between) return { minPrice: +between[1], maxPrice: +between[2] };
  const under = q.match(/(?:under|below|less\s+than|upto|up\s+to|within|max(?:imum)?)\s+(\d+)/i);
  if (under) return { minPrice: null, maxPrice: +under[1] };
  const above = q.match(/(?:above|over|more\s+than|min(?:imum)?|at\s+least|starting)\s+(\d+)/i);
  if (above) return { minPrice: +above[1], maxPrice: null };
  return { minPrice: null, maxPrice: null };
}

function stripPriceClause(q) {
  return q
    .replace(/between\s+[\d,$₹]+\s+(?:and|to)\s+[\d,$₹]+/gi, '')
    .replace(/(?:under|below|less\s+than|upto|up\s+to|within|max(?:imum)?)\s+[\d,₹$]+/gi, '')
    .replace(/(?:above|over|more\s+than|min(?:imum)?|at\s+least|starting)\s+[\d,₹$]+/gi, '')
    .trim();
}

// ════════════════════════════════════════════════════════════════
//  LIMIT EXTRACTION
// ════════════════════════════════════════════════════════════════
function extractLimit(query) {
  const q = query.toLowerCase();
  if (/\ball\b/.test(q) && !/top\s+\d+/.test(q)) return MAX_LIMIT;
  const mt = query.match(/top\s+(\d+)/i);
  if (mt) return Math.min(+mt[1], MAX_LIMIT);
  const ms = query.match(/show\s+(?:me\s+)?(\d+)/i);
  if (ms) return Math.min(+ms[1], MAX_LIMIT);
  return DEFAULT_LIMIT;
}

// ════════════════════════════════════════════════════════════════
//  SORT DETECTION
// ════════════════════════════════════════════════════════════════
function resolveSort(query) {
  const q = query.toLowerCase();
  if (/cheapest|lowest\s+price|most\s+affordable/.test(q)) return 'price_asc';
  if (/most\s+expensive|highest\s+price|luxury/.test(q))    return 'price_desc';
  if (/top\s+rated|highest\s+rated|best\s+rated/.test(q))   return 'rating_desc';
  if (/best\s+selling|most\s+popular|trending/.test(q))     return 'best_selling';
  return 'best';
}

// ════════════════════════════════════════════════════════════════
//  GENDER DETECTION
//  Used as a Solr fq filter for categories where the `gender` field
//  is reliably tagged (e.g. apparel-kids-boy-*, apparel-kids-girl-*,
//  apparel-women-*, apparel-men-*). For apparel-kids-baby-* the
//  `gender` field is hardcoded to "Baby" in the data regardless of
//  actual boy/girl product, so it's unreliable there — see
//  filterByNameGender() below for that case.
// ════════════════════════════════════════════════════════════════
function detectGender(query) {
  const q = stripPriceClause(query).toLowerCase();
  const forBaby  = /(baby|infant|toddler)/.test(q);
  const forKids  = /(kid|child|junior)/.test(q) || forBaby;
  const forBoy   = /\bboys?\b/.test(q);
  const forGirl  = /\bgirls?\b/.test(q);
  const forWomen = /(women|woman|female|ladies|lady)/.test(q) && !forKids;
  const forMen   = /(men|man|male|gents)/.test(q) && !forKids && !forWomen;

  if (forBoy)   return 'Boys';
  if (forGirl)  return 'Girls';
  if (forWomen) return 'Women';
  if (forMen)   return 'Men';
  return null;
}

// ════════════════════════════════════════════════════════════════
//  NAME-BASED GENDER FILTER
//  Fallback filter for categories (currently: apparel-kids-baby-*)
//  where the Solr `gender` field can't be trusted. Filters the
//  already-fetched doc list by matching Boy(s)/Girl(s) in the
//  product name. Falls back to the unfiltered list if too few
//  matches are found, since some baby items are genuinely unisex
//  and have no gender word in the name at all.
// ════════════════════════════════════════════════════════════════
function filterByNameGender(docs, genderFilter) {
  if (!genderFilter) return docs;
  const pattern = genderFilter === 'Boys' ? /\bboys?\b/i
                 : genderFilter === 'Girls' ? /\bgirls?\b/i
                 : null;
  if (!pattern) return docs;

  const matched = docs.filter(d => pattern.test(d.name || ''));
  // Fall back to unfiltered ONLY when zero matches exist (truly unisex items).
  // >= 3 was wrong — it caused girls items to show when only 2 boys items existed.
  return matched.length > 0 ? matched : docs;
}

// ════════════════════════════════════════════════════════════════
//  PHONE MODEL DETECTION
//  Detects specific phone model strings (e.g. "s23", "iphone 14")
//  so accessory queries like "s23 case" route correctly without
//  applying the phone-brand filter (the case brand ≠ phone brand).
// ════════════════════════════════════════════════════════════════
const PHONE_MODELS = [
  // Samsung Galaxy series
  'galaxy s23 ultra','galaxy s23+','galaxy s23 plus','galaxy s23',
  'galaxy s22 ultra','galaxy s22+','galaxy s22 plus','galaxy s22',
  'galaxy s21 ultra','galaxy s21+','galaxy s21 plus','galaxy s21',
  'galaxy s20 ultra','galaxy s20+','galaxy s20 plus','galaxy s20',
  'galaxy s10+','galaxy s10 plus','galaxy s10e','galaxy s10',
  'galaxy a73','galaxy a72','galaxy a53','galaxy a52','galaxy a33','galaxy a32',
  'galaxy a23','galaxy a13','galaxy note 20','galaxy note 10','galaxy note10',
  's23 ultra','s23+','s23 plus','s23',
  's22 ultra','s22+','s22 plus','s22',
  's21 ultra','s21+','s21 plus','s21',
  's20 ultra','s20+','s20 plus','s20',
  's10+','s10 plus','s10e','s10',
  'note 20 ultra','note 20','note10 plus','note10','note 9',
  // Apple iPhone
  'iphone 15 pro max','iphone 15 pro','iphone 15 plus','iphone 15',
  'iphone 14 pro max','iphone 14 pro','iphone 14 plus','iphone 14',
  'iphone 13 pro max','iphone 13 pro','iphone 13 mini','iphone 13',
  'iphone 12 pro max','iphone 12 pro','iphone 12 mini','iphone 12',
  'iphone 11 pro max','iphone 11 pro','iphone 11',
  'iphone se','iphone xs','iphone xr','iphone x',
  // OnePlus
  'oneplus 12','oneplus 11','oneplus 10 pro','oneplus 10','oneplus 9 pro','oneplus 9',
  // Pixel
  'pixel 8 pro','pixel 8','pixel 7 pro','pixel 7','pixel 6 pro','pixel 6',
  // Motorola
  'moto g84','moto g73','moto g54','moto g53','moto edge 40',
];

function detectPhoneModel(query) {
  const q = query.toLowerCase();
  // Sort longest first to avoid partial matches
  for (const model of PHONE_MODELS) {
    if (q.includes(model)) return model;
  }
  return null;
}

// ════════════════════════════════════════════════════════════════
//  ACCESSORY TYPE DETECTION
//  Used when a phone model is detected to route to the right
//  accessory category.
// ════════════════════════════════════════════════════════════════
function detectAccessoryType(query) {
  const q = query.toLowerCase();
  if (/(back\s*cover|phone\s*case|\bcase\b|cover|bumper|armor|wallet\s*case|flip\s*case|clear\s*case)/.test(q))
    return 'mobile-and-accessories-accessories-protection-back-covers';
  if (/(screen\s*guard|screen\s*protector|tempered\s*glass|glass\s*protector|screen\s*film)/.test(q))
    return 'mobile-and-accessories-accessories-protection-screen-protectors';
  if (/(charger|charging\s*cable|fast\s*charger|wireless\s*charger)/.test(q))
    return 'mobile-and-accessories-accessories-chargers';
  return null;
}

// ════════════════════════════════════════════════════════════════
//  CATEGORY PREFIX DETECTION
//  Runs on price-stripped query. Returns the most specific
//  matching categoryId prefix, or null for broad search.
// ════════════════════════════════════════════════════════════════
function detectCategoryPrefix(query) {
  const raw = stripPriceClause(query);
  const q   = raw.toLowerCase();

  // ── MOBILE & ACCESSORIES ──────────────────────────────────────
  // Phone model + accessory → handled by detectPhoneModel above
  // Generic accessory keywords first (before phone brand detection)
  if (/(screen\s*guard|screen\s*protector|tempered\s*glass|glass\s*protector)/.test(q))
    return 'mobile-and-accessories-accessories-protection-screen-protectors';
  if (/(back\s*cover|phone\s*case|mobile\s*cover|mobile\s*case)/.test(q))
    return 'mobile-and-accessories-accessories-protection-back-covers';
  if (/wireless\s+charger|charger.*wireless/.test(q))
    return 'mobile-and-accessories-accessories-chargers-wireless-chargers';
  if (/(fast\s+charger|charger|charging\s+cable|usb\s+cable)/.test(q))
    return 'mobile-and-accessories-accessories-chargers-fast-chargers';
  if (/(wired\s+earphone|earphone|wired\s+headphone)/.test(q))
    return 'mobile-and-accessories-accessories-audio-wired-earphones';
  if (/(wireless\s+headphone|bluetooth\s+headphone|over.?ear|on.?ear)/.test(q))
    return 'mobile-and-accessories-accessories-audio-wireless-headphones';
  if (/(tws|true\s+wireless|earbud|wireless\s+earphone|bluetooth\s+earphone|airpod)/.test(q))
    return 'mobile-and-accessories-accessories-audio-wireless-headphones';

  if (/(feature\s+phone|keypad\s+phone|basic\s+phone|button\s+phone)/.test(q))
    return 'mobile-and-accessories-feature-phones';

  if (/(mobile|smartphone|phone|5g\s+phone)/.test(q)) {
    if (/apple|iphone/.test(q))    return 'mobile-and-accessories-smartphones-brands-apple';
    if (/samsung/.test(q))         return 'mobile-and-accessories-smartphones-brands-samsung';
    if (/oneplus/.test(q))         return 'mobile-and-accessories-smartphones-brands-oneplus';
    if (/xiaomi|redmi|poco/.test(q)) return 'mobile-and-accessories-smartphones-brands-xiaomi';
    if (/realme/.test(q))          return 'mobile-and-accessories-smartphones-brands-realme';
    if (/oppo/.test(q))            return 'mobile-and-accessories-smartphones-brands-oppo';
    if (/vivo/.test(q))            return 'mobile-and-accessories-smartphones-brands-vivo';
    if (/motorola|moto\b/.test(q)) return 'mobile-and-accessories-smartphones-brands-motorola';
    if (/nothing/.test(q))         return 'mobile-and-accessories-smartphones-brands-nothing';
    if (/gaming/.test(q))          return 'mobile-and-accessories-smartphones-gaming-phones';
    if (/camera/.test(q))          return 'mobile-and-accessories-smartphones-camera-phones';
    if (/budget|cheap|entry/.test(q)) return 'mobile-and-accessories-smartphones-budget-phones';
    if (/mid.?range/.test(q))      return 'mobile-and-accessories-smartphones-mid-range-phones';
    if (/premium|flagship/.test(q)) return 'mobile-and-accessories-smartphones-premium-phones';
    if (/battery/.test(q))         return 'mobile-and-accessories-smartphones-battery-phones';
    return 'mobile-and-accessories-smartphones';
  }

  // ── SHOES ─────────────────────────────────────────────────────
  if (/(shoe|sneaker|boot|sandal|slipper|footwear|loafer|moccasin|heel|flat|pump|flip.?flop|oxford|derby|brogue|espadrille|boat\s+shoe|ballet|clog|mule|jutti|mojari|kolhapuri|wedge)/.test(q)) {
    const forBaby  = /(baby|toddler|infant)/.test(q);
    const forKids  = /(kid|child|junior)/.test(q) || forBaby;
    const forBoy   = /\bboy\b/.test(q);
    const forGirl  = /\bgirl\b/.test(q);
    const forWomen = /(women|woman|female|ladies|lady)/.test(q) && !forKids;
    const forMen   = /(men|man|male|gents)/.test(q) && !forKids && !forWomen;

    // Type-specific mapping
    if (/(loafer|moccasin)/.test(q)) {
      if (forWomen) return 'shoes-women-casual-shoes-loafers-moccasins';
      if (forMen)   return 'shoes-men-casual-shoes-loafers-moccasins';
      if (forBoy)   return 'shoes-kids-boys-casual-shoes-loafers-moccasins';
      if (forGirl)  return 'shoes-kids-girls-casual-shoes-loafers-moccasins';
      return 'shoes'; // broad — let BM25 find best gender match
    }
    if (/running/.test(q)) {
      if (forWomen) return 'shoes-women-sports-outdoor-shoes-running-shoes';
      if (forMen)   return 'shoes-men-sports-and-outdoor-running-shoes';
      if (forBoy)   return 'shoes-kids-boys-sports-outdoor-shoes-running-shoes';
      if (forGirl)  return 'shoes-kids-girls-sports-outdoor-shoes-running-shoes';
      if (forKids)  return 'shoes-kids';
      return 'shoes';
    }
    if (/(trek|hiking)/.test(q)) {
      if (forWomen) return 'shoes-women-sports-outdoor-shoes-trekking-hiking-footwear';
      if (forMen)   return 'shoes-men-sports-and-outdoor-trekking-hiking-footwear';
      return 'shoes';
    }
    if (/(training|workout|gym\s+shoe)/.test(q)) {
      if (forWomen) return 'shoes-women-sports-outdoor-shoes-training-shoes';
      if (forMen)   return 'shoes-men-sports-and-outdoor-training-shoes';
      return 'shoes';
    }
    if (/(walk|walking)/.test(q)) {
      if (forWomen) return 'shoes-women-sports-outdoor-shoes-walking-shoes';
      if (forMen)   return 'shoes-men-sports-and-outdoor-walking-shoes';
      return 'shoes';
    }
    if (/(oxford|formal\s+shoe|derby|brogue)/.test(q)) {
      if (forWomen) return 'shoes-women-formal-shoes';
      if (forMen)   return 'shoes-men-formal-shoes-oxford';
      return 'shoes';
    }
    if (/formal/.test(q)) {
      if (forWomen) return 'shoes-women-formal-shoes';
      if (forMen)   return 'shoes-men-formal-shoes-oxford';
      return 'shoes';
    }
    if (/sandal|floater/.test(q)) {
      if (forWomen) return 'shoes-women-sandles-floaters-flats';
      if (forMen)   return 'shoes-men-sandles-floaters';
      if (forBoy)   return 'shoes-kids-boys-sandals-floaters-beach-sandals-pool-shoes';
      if (forGirl)  return 'shoes-kids-girls-sandles';
      return 'shoes';
    }
    if (/sneaker|casual/.test(q)) {
      if (forWomen) return 'shoes-women-casual-shoes-sneakers';
      if (forMen)   return 'shoes-men-casual-shoes-sneakers';
      if (forBoy)   return 'shoes-kids-boys-casual-shoes-sneakers';
      if (forGirl)  return 'shoes-kids-girls-casual-shoes-sneakers';
      return 'shoes';
    }
    if (/(boot)/.test(q)) {
      if (forWomen) return 'shoes-women-boots';
      if (forMen)   return 'shoes-men-casual-shoes-boots';
      return 'shoes';
    }
    if (/(ballet|flat)/.test(q)) {
      if (forWomen) return 'shoes-women-ballet-flats';
      if (forGirl)  return 'shoes-kids-girls-ballet-flats';
      return 'shoes-women';
    }
    if (/(heel|pump)/.test(q)) {
      if (forWomen) return 'shoes-women-sandles-floaters-heels';
      return 'shoes-women';
    }
    if (/espadrille/.test(q)) {
      if (forWomen) return 'shoes-women-casual-shoes-espadrille-flats';
      return 'shoes-women';
    }
    if (/ethnic|jutti|mojari|kolhapuri/.test(q)) {
      if (forMen) return 'shoes-men-ethnic';
      return 'shoes';
    }
    if (/(flip.?flop|slipper|slide)/.test(q)) {
      if (forWomen) return 'shoes-women-flip-flops-slippers';
      if (forMen)   return 'shoes-men-flip-flops-slippers';
      return 'shoes';
    }
    if (/football/.test(q)) {
      if (forMen)  return 'shoes-men-sports-and-outdoor-football-shoes';
      if (forBoy)  return 'shoes-kids-boys-sports-outdoor-shoes-football-shoes';
      if (forGirl) return 'shoes-kids-girls-sports-outdoor-shoes-football-shoes';
      return 'shoes';
    }
    if (/(school\s+shoe)/.test(q)) {
      if (forBoy)  return 'shoes-kids-boys-school-shoes';
      if (forGirl) return 'shoes-kids-girls-school-shoes';
      return 'shoes-kids';
    }
    if (forBaby)  return 'shoes-kids-baby-shoes';
    if (forGirl)  return 'shoes-kids-girls';
    if (forBoy)   return 'shoes-kids-boys';
    if (forKids)  return 'shoes-kids';
    if (forWomen) return 'shoes-women';
    if (forMen)   return 'shoes-men';
    return 'shoes';
  }

  // ── APPAREL ───────────────────────────────────────────────────
  if (/(cloth|apparel|wear|shirt|tshirt|t-shirt|t shirt|trouser|pant|jean|dress|kurta|saree|kurti|top|jacket|sweatshirt|hoodie|sweater|coat|blazer|suit|inner|brief|boxer|bra|panty|lingerie|pyjama|pajama|nightwear|swimwear|legging|skirt|short|cargo|vest|camisole|romper|bodysuit|tracksuit|salwar|dupatta|anarkali|kurti|chunni|gown|shrug|poncho|cape|rainwear|maternity|shapewear|thermal|trackpant|track pant|athletic|sportswear)/.test(q)) {
    const forBaby  = /(baby|infant|toddler)/.test(q);
    const forKids  = /(kid|child|junior)/.test(q) || forBaby;
    const forBoy   = /\bboy\b/.test(q) && forKids;
    const forGirl  = /\bgirl\b/.test(q) && forKids;
    const forWomen = /(women|woman|female|ladies|lady)/.test(q) && !forKids;
    const forMen   = /(men|man|male|gents)/.test(q) && !forKids && !forWomen;

    if (forKids) {
      if (forBaby) {
        if (/(set|clothing\s*set)/.test(q))           return 'apparel-kids-baby-clothing-clothing-sets';
        if (/romper/.test(q))                          return 'apparel-kids-baby-clothing-rompers';
        if (/(winter|coat|sweater|sweatshirt)/.test(q)) return 'apparel-kids-baby-clothing-winter-wear-sweaters';
        if (/(pyjama|pajama|sleepwear)/.test(q))       return 'apparel-kids-baby-clothing-sleepwear-pyjama-sets';
        if (/shirt/.test(q))                           return 'apparel-kids-baby-clothing-shirts';
        if (/(tshirt|t-shirt|t shirt)/.test(q))        return 'apparel-kids-baby-clothing-t-shirts';
        return 'apparel-kids-baby-clothing';
      }
      if (forBoy) {
        if (/(tshirt|t-shirt|t shirt|tee|polo)/.test(q)) return 'apparel-kids-boy-clothing-t-shirts-polos-tees';
        if (/jean/.test(q))                             return 'apparel-kids-boy-clothing-jeans';
        if (/(pant|trouser)/.test(q))                   return 'apparel-kids-boy-clothing-pants';
        if (/(inner|brief|boxer|trunk)/.test(q))        return 'apparel-kids-boy-clothing-innerwear-briefs';
        if (/(swimwear|swim)/.test(q))                  return 'apparel-kids-boy-clothing-swimwear-shorts-trunks';
        if (/(suit|blazer)/.test(q))                    return 'apparel-kids-boy-clothing-suits-blazers-suits';
        if (/(pyjama|pajama|sleep)/.test(q))            return 'apparel-kids-boy-clothing-sleepwear-pyjamas';
        return 'apparel-kids-boy-clothing';
      }
      if (forGirl) {
        if (/dress/.test(q))                            return 'apparel-kids-girl-clothing-dresses-jumpsuits';
        if (/(top|tshirt|t-shirt|t shirt)/.test(q))    return 'apparel-kids-girl-clothing-tops-t-shirts-shirts-t-shirts';
        if (/skirt/.test(q))                            return 'apparel-kids-girl-clothing-skirts-shorts-skirts';
        if (/(inner|panty)/.test(q))                    return 'apparel-kids-girl-clothing-innerwear-panties';
        if (/legging/.test(q))                          return 'apparel-kids-girl-clothing-tights-leggings';
        if (/jean/.test(q))                             return 'apparel-kids-girl-clothing-jeans';
        if (/(pant|trouser)/.test(q))                   return 'apparel-kids-girl-clothing-pants';
        if (/(swimwear|swim)/.test(q))                  return 'apparel-kids-girl-clothing-swimwear';
        if (/(sleep|pyjama|pajama)/.test(q))            return 'apparel-kids-girl-clothing-sleepwear';
        return 'apparel-kids-girl-clothing';
      }
      return 'apparel-kids';
    }

    if (forWomen) {
      if (/saree/.test(q))                              return 'apparel-women-ethnic-wear-sarees';
      if (/(kurta|kurti|anarkali)/.test(q))             return 'apparel-women-ethnic-wear-kurtas-kurtis';
      if (/salwar/.test(q))                             return 'apparel-women-ethnic-wear-salwar-suits';
      if (/gown/.test(q))                               return 'apparel-women-ethnic-wear-gowns';
      if (/chunni|dupatta/.test(q))                     return 'apparel-women-ethnic-wear-chunnis-dupattas';
      if (/maternity/.test(q))                          return 'apparel-women-maternity-ethnic-wear';
      if (/\bbra\b/.test(q))                            return 'apparel-women-Lingerie-bras';
      if (/panty|panties/.test(q))                      return 'apparel-women-lingerie-panties';
      if (/camisole|camis|tank\s+top/.test(q))          return 'apparel-women-lingerie-camisoles-tanks';
      if (/shapewear/.test(q))                          return 'apparel-women-lingerie-shapewear';
      if (/nightie|nightdress|nightwear\s+dress/.test(q)) return 'apparel-women-sleep-lounge-wear-nighties-nightdresses';
      if (/(pyjama|pajama|nightwear|lounge)/.test(q))   return 'apparel-women-sleep-lounge-wear-pyjama-sets';
      if (/swimwear|bikini/.test(q))                    return 'apparel-women-swim-beachwear-bikinis';
      if (/legging.*sport|sport.*legging/.test(q))      return 'apparel-women-sportswear-leggings';
      if (/(sweatshirt|hoodie).*sport|sport.*(sweatshirt|hoodie)/.test(q)) return 'apparel-women-sportswear-sweatshirts-hoodies';
      if (/(sport|athletic|workout|gym|fitness)/.test(q)) return 'apparel-women-sportswear';
      if (/legging/.test(q))                            return 'apparel-women-western-wear-leggings';
      if (/(dress|jumpsuit)/.test(q))                   return 'apparel-women-western-wear-dresses-jumpsuits';
      if (/(jean|jegging)/.test(q))                     return 'apparel-women-western-wear-jeans-jeggings';
      if (/(top|tshirt|t-shirt|t shirt)/.test(q))       return 'apparel-women-western-wear-tops-t-shirts-shirts';
      if (/(trouser|pant)/.test(q))                     return 'apparel-women-western-wear-trousers';
