function detectBrand(query) {
  const stripped = stripPriceClause(query).toLowerCase();
  // Longest key first so "under armour" matches before "under"
  for (const key of Object.keys(BRAND_MAP).sort((a, b) => b.length - a.length)) {
    if (stripped.includes(key)) return { key, ...BRAND_MAP[key] };
  }
  return null;
}

