const _embedCache = new Map();
async function getEmbedding(text) {
  if (_embedCache.has(text)) return _embedCache.get(text);
  try {
    const res = await fetch(EMBED_URL, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({ text }),
    });
    const emb = await res.json();
    if (!Array.isArray(emb) || emb.length !== 384) throw new Error('bad dims');
    _embedCache.set(text, emb);
    return emb;
  } catch (e) {
    console.error('Embedding skipped:', e.message);
    return null;
  }
}

// ════════════════════════════════════════════════════════════════
//  BM25 (edismax)
//  — name is primary signal
//  — brand field boosted for brand queries
//  — model keywords (like "s23") surface in name matches via BM25
// ════════════════════════════════════════════════════════════════
async function searchBM25(query, price, categoryPrefix, brandSolrFilter, phoneModel, genderFilter) {
  const params = new URLSearchParams();
  params.append('defType', 'edismax');

  // If a phone model was detected, inject model into query to surface
  // accessories that mention the model string in the product name
  const bm25Query = phoneModel
    ? `${query} ${phoneModel}`   // e.g. "s23 case s23"
    : query;

  params.append('q', bm25Query);
  // brand field added alongside name for stronger brand-match signal
  params.append('qf',  'name^20 brand^12 categoryId^6 description^2');
  params.append('pf',  'name^15 brand^10');
  params.append('pf2', 'name^8');
  params.append('mm',  '2<75%');

  if (categoryPrefix)          params.append('fq', `categoryId:${categoryPrefix}*`);
  if (brandSolrFilter)         params.append('fq', brandSolrFilter);
  if (genderFilter)            params.append('fq', `gender:${genderFilter}`);
  if (price.maxPrice != null)  params.append('fq', `sellingPrice:[* TO ${price.maxPrice}]`);
  if (price.minPrice != null)  params.append('fq', `sellingPrice:[${price.minPrice} TO *]`);

  params.append('fl', 'id,sku,name,description,categoryId,sellingPrice,averageRating,performanceScore,imageurls,gender,brand,score');
  params.append('rows', FETCH_K);
  params.append('timeAllowed', '4000');
  params.append('wt', 'json');

  const res = await fetch(SOLR_URL, {
    method:  'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Authorization': `Basic ${AUTH}` },
    body:    params.toString(),
  });
  if (!res.ok) throw new Error(`Solr BM25 HTTP ${res.status}`);
  const data = await res.json();
  return { docs: data.response?.docs || [], numFound: data.response?.numFound || 0 };
}

// ════════════════════════════════════════════════════════════════
//  KNN (semantic)
// ════════════════════════════════════════════════════════════════
async function searchKNN(embedding, price, categoryPrefix, brandSolrFilter, genderFilter) {
  if (!embedding) return { docs: [], numFound: 0 };
  const vectorStr = embedding.map(v => Number(v).toFixed(6)).join(',');
  const params = new URLSearchParams();
  params.append('q', `{!knn f=vector topK=${FETCH_K}}[${vectorStr}]`);

  if (categoryPrefix)          params.append('fq', `categoryId:${categoryPrefix}*`);
  if (brandSolrFilter)         params.append('fq', brandSolrFilter);
  if (genderFilter)            params.append('fq', `gender:${genderFilter}`);
  if (price.maxPrice != null)  params.append('fq', `sellingPrice:[* TO ${price.maxPrice}]`);
  if (price.minPrice != null)  params.append('fq', `sellingPrice:[${price.minPrice} TO *]`);

  params.append('fl', 'id,sku,name,description,categoryId,sellingPrice,averageRating,performanceScore,imageurls,gender,brand,score');
  params.append('rows', FETCH_K);
  params.append('timeAllowed', '4000');
  params.append('wt', 'json');

  try {
    const res = await fetch(SOLR_URL, {
      method:  'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Authorization': `Basic ${AUTH}` },
      body:    params.toString(),
    });
    if (!res.ok) throw new Error(`Solr KNN HTTP ${res.status}`);
    const data = await res.json();
    return { docs: data.response?.docs || [], numFound: data.response?.numFound || 0 };
  } catch (e) {
    console.warn('KNN failed:', e.message);
    return { docs: [], numFound: 0 };
  }
}

// ════════════════════════════════════════════════════════════════
//  RRF FUSION  (BM25 weighted 1.5×, KNN 0.5×)
// ════════════════════════════════════════════════════════════════
function rrfFusion(bm25Docs, knnDocs, k = 60) {
  const scores = new Map();
  bm25Docs.forEach((doc, i) => {
    const s = 1.5 / (k + i + 1);
    if (!scores.has(doc.id)) scores.set(doc.id, { ...doc, rrfScore: 0 });
    scores.get(doc.id).rrfScore += s;
  });
  knnDocs.forEach((doc, i) => {
    const s = 0.5 / (k + i + 1);
    if (!scores.has(doc.id)) scores.set(doc.id, { ...doc, rrfScore: 0 });
    scores.get(doc.id).rrfScore += s;
  });
  return Array.from(scores.values()).sort((a, b) => b.rrfScore - a.rrfScore);
}

// ════════════════════════════════════════════════════════════════
//  HYBRID SEARCH ORCHESTRATOR
// ════════════════════════════════════════════════════════════════
async function hybridSearch(query, price, categoryPrefix, brandSolrFilter, embedding, phoneModel, genderFilter) {
  const [bm25Res, knnRes] = await Promise.all([
    searchBM25(query, price, categoryPrefix, brandSolrFilter, phoneModel, genderFilter),
    searchKNN(embedding, price, categoryPrefix, brandSolrFilter, genderFilter),
  ]);
  const fused = knnRes.docs.length > 0
    ? rrfFusion(bm25Res.docs, knnRes.docs)
    : bm25Res.docs;
  return { docs: fused, numFound: bm25Res.numFound };
}

// ════════════════════════════════════════════════════════════════
//  PHONE MODEL RELEVANCE BOOST
//  Re-ranks accessory results to surface model-specific ones first
// ════════════════════════════════════════════════════════════════
function boostByPhoneModel(docs, phoneModel) {
  if (!phoneModel) return docs;
  const model = phoneModel.toLowerCase();
  return docs.map(doc => {
    const nameLC = (doc.name || '').toLowerCase();
    const descLC = (doc.description || '').toLowerCase();
    const modelMatch = nameLC.includes(model) || descLC.includes(model);
    return { ...doc, _modelBoost: modelMatch ? 2.0 : 0 };
  }).sort((a, b) => b._modelBoost - a._modelBoost || (b.rrfScore || 0) - (a.rrfScore || 0));
}

// ════════════════════════════════════════════════════════════════
//  RANKING ENGINE
// ════════════════════════════════════════════════════════════════
function priceScore(price, minPrice, maxPrice) {
  if (maxPrice && minPrice) {
    const ratio = (price - minPrice) / (maxPrice - minPrice);
    return ratio >= 0.6 ? 1.0 : ratio >= 0.3 ? 0.7 : 0.4;
  }
  if (maxPrice) {
    const ratio = price / maxPrice;
    return ratio >= 0.7 ? 1.0 : ratio >= 0.5 ? 0.7 : ratio >= 0.3 ? 0.4 : 0.2;
  }
  return 0;
}

function rankProducts(docs, sortBy, minPrice, maxPrice, categoryPrefix, query) {
  const q = (query || '').toLowerCase();

  // Adaptive rating floor
  function getMinRating(prefix, maxP) {
    if (maxP && maxP <= 1000) return 3.0;
    if (maxP && maxP <= 3000) return 3.5;
    if (!prefix) return 4.0;
    if (/(smartphone|mobile)/.test(prefix)) return 4.0;
    if (/shoes/.test(prefix))              return 4.0;
    if (/apparel/.test(prefix))            return 3.8;
    if (/protection|back-cover|screen/.test(prefix)) return 3.5;
    return 4.0;
  }

  const MIN_RATING = getMinRating(categoryPrefix, maxPrice);
  let filtered = docs.filter(d => (d.averageRating || 0) >= MIN_RATING);
  if (filtered.length < 3) filtered = docs.filter(d => (d.averageRating || 0) >= 3.5);
  if (filtered.length < 3) filtered = docs.filter(d => (d.averageRating || 0) >= 3.0);
  if (filtered.length === 0) filtered = docs;

  // Deduplication — first 4 words of name
  const seen = new Set();
  filtered = filtered.filter(doc => {
    const key = (doc.name || '').toLowerCase().split(/\s+/).slice(0, 4).join(' ');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const isBest    = /best/.test(q);
  const isPremium = /premium|expensive|flagship/.test(q);

  const scored = filtered.map(doc => {
    const rating = doc.averageRating || 0;
    const perf   = Math.log10(Math.max(doc.performanceScore || 1, 1));
    const rrf    = doc.rrfScore || 0;
    const bm25   = doc.score    || 0;
    const pScore = priceScore(doc.sellingPrice || 0, minPrice, maxPrice);
    const mBoost = doc._modelBoost || 0;

    let _score;
    if (sortBy === 'rating_desc')       _score = rating * 6 + rrf * 1.0 + perf * 0.3;
    else if (sortBy === 'best_selling') _score = perf * 4 + rating * 3 + rrf * 1.5;
    else {
      _score = rrf * 4.0 + bm25 * 2.0 + rating * 2.5 + pScore * 1.5 + perf * 0.5 + mBoost * 3.0;
      if (isBest)    _score += rating * 2.0 + perf * 1.0;
      if (isPremium) _score += perf * 2.0 + rating * 1.0;
    }
    return { ...doc, _score };
  });

  if (sortBy === 'price_asc')  return scored.sort((a, b) => (a.sellingPrice || 0) - (b.sellingPrice || 0));
  if (sortBy === 'price_desc') return scored.sort((a, b) => (b.sellingPrice || 0) - (a.sellingPrice || 0));
  return scored.sort((a, b) => b._score - a._score);
}

// ════════════════════════════════════════════════════════════════
//  DESCRIPTION QUALITY FILTER
// ════════════════════════════════════════════════════════════════
const GENERIC_DESC_PATTERNS = [
  /smart performance[\s,]*everyday convenience/i,
  /built for comfort[\s,]*designed for daily wear/i,
  /essential quality[\s,]*exceptional value/i,
  /quality you can trust/i,
  /everyday essential/i,
  /soft comfort[\s,]*everyday ease/i,
  /timeless style[\s,]*modern comfort/i,
  /timeless style[\s,]*modern confidence/i,
  /refined style[\s,]*everyday comfort/i,
  /sporty style[\s,]*everyday comfort/i,
  /rugged style[\s,]*everyday support/i,
  /easy style[\s,]*warm.?weather comfort/i,
  /practical design[\s,]*everyday utility/i,
  /fast power[\s,]*everyday convenience/i,
  /classic style[\s,]*flexible comfort/i,
  /reliable comfort for everyday/i,
  /simple style[\s,]*all.?day ease/i,
  /soft comfort[\s,]*relaxed support/i,
  /lightweight comfort[\s,]*everyday use/i,
  /modern comfort[\s,]*everyday style/i,
  /everyday comfort[\s,]*everyday style/i,
  /clear protection[\s,]*daily confidence/i,
  /^[a-z]+ style,\s+[a-z]+ (comfort|support|ease|confidence|convenience)\.?$/i,
  /^[a-z]+ comfort,\s+[a-z]+ (style|ease|support|confidence|wear)\.?$/i,
];

function cleanDescription(rawDesc) {
  if (!rawDesc) return null;
  const firstLine = rawDesc.replace(/\*\*/g, '').split('\n')[0].trim();
  if (firstLine.length < 25) return null;
  if (GENERIC_DESC_PATTERNS.some(re => re.test(firstLine))) return null;
  // Extract first meaningful bullet/sentence if available
  const lines = rawDesc.replace(/\*\*/g, '').split('\n');
  for (const line of lines) {
    const clean = line.replace(/^[\s•\-*]+/, '').trim();
    if (clean.length > 30 && !GENERIC_DESC_PATTERNS.some(re => re.test(clean))) {
      return clean.length > 180 ? clean.slice(0, 177) + '...' : clean;
    }
  }
  if (firstLine.length > 180) return firstLine.slice(0, 177) + '...';
  return firstLine;
}

