// ════════════════════════════════════════════════════════════════
//  FORMAT RESULTS
// ════════════════════════════════════════════════════════════════
function formatResults(docs, query, numFound, limit) {
  const products = docs.map((doc, idx) => ({
    rank:        idx + 1,
    name:        doc.name,
    sku:         doc.sku || doc.id,
    categoryId:  doc.categoryId,
    brand:       (doc.brand && doc.brand !== 'NaN') ? doc.brand : null,
    gender:      (doc.gender && doc.gender !== 'NaN' && doc.gender !== 'nan') ? doc.gender : null,
    price:       doc.sellingPrice != null ? `$${Number(doc.sellingPrice).toFixed(2)}` : 'N/A',
    rating:      doc.averageRating != null ? `${Number(doc.averageRating).toFixed(1)}/5` : 'N/A',
    description: cleanDescription(doc.description || null),
    image:       doc.imageurls?.[0] || null,
  }));

  const correctedTotal = Math.max(numFound, products.length);
  const hasMore = correctedTotal > products.length;

  return {
    query,
    totalInDatabase: correctedTotal,
    returnedCount:   products.length,
    hasMore,
    resultSummary: hasMore
      ? `Showing top ${products.length} of ${correctedTotal} results.`
      : `Showing all ${products.length} results.`,
    products,
  };
}

