    const accessoryCat = detectAccessoryType(query);
    if (accessoryCat) {
      // e.g. "s23 case" → back-covers category, NO brand filter (case brand ≠ phone brand)
      categoryPrefix = accessoryCat;
      // intentionally skip brand filter for model-accessory queries
    } else {
      // "Samsung S23 phone" → phone category
      categoryPrefix = detectCategoryPrefix(query);
    }
  } else {
    categoryPrefix = detectCategoryPrefix(query);
  }

  // ── Brand filter ─────────────────────────────────────────────
  let brandSolrFilter = null;
  if (brandInfo && !phoneModel) {
    // Only apply brand filter when no phone model detected
    // (avoids filtering out "Galaxy S23 case" by brand=Samsung when case brand is Spigen)
    brandSolrFilter = brandInfo.solrFilter;
    if (!categoryPrefix && brandInfo.categoryPrefix) {
      categoryPrefix = brandInfo.categoryPrefix;
    }
  } else if (brandInfo && phoneModel) {
    // Phone brand detected alongside phone model → this IS a phone search, not accessory
    if (!detectAccessoryType(query)) {
      brandSolrFilter = brandInfo.solrFilter;
      categoryPrefix  = categoryPrefix || brandInfo.categoryPrefix;
    }
  }

  // ── Gender handling ──────────────────────────────────────────
  // For apparel-kids-baby-*, the Solr `gender` field is hardcoded to
  // "Baby" regardless of actual boy/girl product, so a Solr fq filter
  // on gender is useless there. Instead, skip the fq and post-filter
  // the fetched docs by matching Boy(s)/Girl(s) in the product name.
  // All other categories (women/men/kids-boy/kids-girl) keep using
  // the normal Solr fq:gender filter, which is unaffected by this change.
  const needsNameGenderFilter = !!(categoryPrefix && categoryPrefix.startsWith('apparel-kids-baby'));
  const solrGenderFilter = needsNameGenderFilter ? null : genderFilter;

  const embedding = await getEmbedding(query);

  // ── Primary search ───────────────────────────────────────────
  let { docs, numFound } = await hybridSearch(
    query, price, categoryPrefix, brandSolrFilter, embedding, phoneModel, solrGenderFilter
  );

  // Apply phone-model boost for accessory queries
  if (phoneModel && detectAccessoryType(query)) {
    docs = boostByPhoneModel(docs, phoneModel);
  }

  // Apply name-based gender filter for baby clothing
  if (needsNameGenderFilter) {
    docs = filterByNameGender(docs, genderFilter);
  }

  // ── Category relevance guard ─────────────────────────────────
  // Extracts the top-level domain (apparel / shoes / mobile-and-accessories)
  // so we can strip cross-category bleed after any fallback fires.
  function topLevelCategory(prefix) {
    if (!prefix) return null;
    if (prefix.startsWith('apparel'))            return 'apparel';
    if (prefix.startsWith('shoes'))              return 'shoes';
    if (prefix.startsWith('mobile'))             return 'mobile';
    return prefix.split('-')[0];
  }

  // Strips docs whose categoryId belongs to a different top-level category.
  // Only applied when a known category was detected — broad queries (null prefix)
  // are intentionally multi-category and should not be filtered.
  function guardCategory(docs, prefix) {
    const top = topLevelCategory(prefix);
    if (!top) return docs;
    return docs.filter(d => (d.categoryId || '').startsWith(top));
  }

  let ranked = rankProducts(docs, sortBy, price.minPrice, price.maxPrice, categoryPrefix, query)
                 .slice(0, limit);

  // Apply category guard on primary results
  if (categoryPrefix) {
    ranked = guardCategory(ranked, categoryPrefix);
  }

  // ── Fallback 1: drop category, keep brand + price ────────────
  // Only fires when truly zero results after guard — not just fewer than 5
  if (ranked.length === 0 && categoryPrefix) {
    const fb = await hybridSearch(query, price, null, brandSolrFilter, embedding, phoneModel, solrGenderFilter);
    let fbDocs = fb.docs;
    if (phoneModel && detectAccessoryType(query)) fbDocs = boostByPhoneModel(fbDocs, phoneModel);
    if (needsNameGenderFilter) fbDocs = filterByNameGender(fbDocs, genderFilter);
    // Still guard by top-level category even without specific prefix
    fbDocs   = guardCategory(fbDocs, categoryPrefix);
    docs     = fbDocs;
    numFound = fb.numFound;
    ranked   = rankProducts(docs, sortBy, price.minPrice, price.maxPrice, null, query).slice(0, limit);
  }

  // ── Fallback 2: drop price filter, keep category + brand ─────
  if (ranked.length === 0 && (price.minPrice != null || price.maxPrice != null)) {
    const fb = await hybridSearch(
      query, { minPrice: null, maxPrice: null }, categoryPrefix, brandSolrFilter, embedding, phoneModel, solrGenderFilter
    );
    let fbDocs = fb.docs;
    if (needsNameGenderFilter) fbDocs = filterByNameGender(fbDocs, genderFilter);
    fbDocs   = guardCategory(fbDocs, categoryPrefix);
    docs     = fbDocs;
    numFound = fb.numFound;
    ranked   = rankProducts(docs, sortBy, null, null, categoryPrefix, query).slice(0, limit);
  }

  // ── Fallback 3: for model-only accessory query, relax to category prefix ─
  // e.g. "s23 case" found 0 → show all back covers
  if (ranked.length === 0 && phoneModel && detectAccessoryType(query)) {
    const looseCat = detectAccessoryType(query);
    const fb = await hybridSearch(query, price, looseCat, null, embedding, null, null);
    docs     = fb.docs;
    numFound = fb.numFound;
    ranked   = rankProducts(docs, sortBy, price.minPrice, price.maxPrice, looseCat, query).slice(0, limit);
  }

  const result = formatResults(ranked, query, numFound, limit);

  if (brandInfo && !phoneModel) {
    result.detectedBrand = brandInfo.label;
    if (ranked.length === 0) result.brandNotFound = true;
  }
  if (phoneModel) {
    result.detectedModel = phoneModel;
  }
  if (ranked.length === 0) {
    const hint = getCategoryHint(query);
    if (hint) result.categoryHint = hint;
  }

  return JSON.stringify(result);

} catch (err) {
  return JSON.stringify({ error: err.message, products: [] });
}
